int gain(TreeNode n) {
    if (n == null) return 0;
    int l = Math.max(0, gain(n.left));
    int r = Math.max(0, gain(n.right));
    maxSum = Math.max(maxSum, n.val + l + r);
    return n.val + Math.max(l, r);
}

int depth(TreeNode n) {
    if (n == null) return 0;
    int l = depth(n.left), r = depth(n.right);
    diameter = Math.max(diameter, l + r);
    return 1 + Math.max(l, r);
}

TreeNode cur = root;
while (cur != null) {
    if (cur.left == null) { res.add(cur.val); cur = cur.right; continue; }
    TreeNode pred = cur.left;
    while (pred.right != null && pred.right != cur) pred = pred.right;
    if (pred.right == null) { pred.right = cur; cur = cur.left; }
    else { pred.right = null; res.add(cur.val); cur = cur.right; }
}

int countNodes(TreeNode root) {
    if (root == null) return 0;
    int lh = 0, rh = 0;
    for (TreeNode n = root; n != null; n = n.left) lh++;
    for (TreeNode n = root; n != null; n = n.right) rh++;
    if (lh == rh) return (1 << lh) - 1;        // perfect tree
    return 1 + countNodes(root.left) + countNodes(root.right);
}
